from browser_use.sandbox.views import SSEEvent, SSEEventType


def test_is_instance_created_guard():
    json_str = json.dumps({
        "type": "instance_created",
        "data": {"session_id": "abc", "live_url": "http://example.com", "status": "ready"},
        "timestamp": "2024-01-01T00:00:00Z"
    })
    event = SSEEvent.from_json(json_str)
    assert event.type == SSEEventType.INSTANCE_CREATED
    assert event.is_instance_created()
    assert not event.is_browser_created()
